function countLandMasses(grid: string[][]): number {
  const R = grid.length, C = grid[0].length;
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  let count = 0;
  for (let r = 0; r < R; r++) {
    for (let c = 0; c < C; c++) {
      if (grid[r][c] !== "#") continue;
      count++;
      grid[r][c] = ".";
      const queue: number[][] = [[r, c]];
      for (let head = 0; head < queue.length; head++) { // head index instead of shift(), which is O(n)
        const [cr, cc] = queue[head];
        for (const [dr, dc] of dirs) {
          const nr = cr + dr, nc = cc + dc;
          if (nr >= 0 && nc >= 0 && nr < R && nc < C && grid[nr][nc] === "#") {
            grid[nr][nc] = "."; // mark on push
            queue.push([nr, nc]);
          }
        }
      }
    }
  }
  return count;
}

