function countLandMasses(grid: string[][]): number {
  const R = grid.length, C = grid[0].length;
  let count = 0;
  for (let r = 0; r < R; r++) {
    for (let c = 0; c < C; c++) {
      if (grid[r][c] !== "#") continue;
      count++;
      grid[r][c] = ".";
      const stack = [r * C + c]; // one number per cell: row * C + col
      while (stack.length) {
        const cell = stack.pop()!, cr = Math.floor(cell / C), cc = cell % C;
        const near = [[cr + 1, cc], [cr - 1, cc], [cr, cc + 1], [cr, cc - 1]];
        for (const [nr, nc] of near) {
          if (nr >= 0 && nc >= 0 && nr < R && nc < C && grid[nr][nc] === "#") {
            grid[nr][nc] = ".";
            stack.push(nr * C + nc);
          }
        }
      }
    }
  }
  return count;
}

